import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.vLhlLNVn.js";const a="/assets/assistent-datenpunkt.BFI7cQOr.png",m=JSON.parse('{"title":"Mein erster Zähler in 10 Minuten","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/01.erste-schritte/02.erster-zaehler.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/erste-schritte/erster-zaehler.md","filePath":"de/adapter/sourceanalytix/erste-schritte/erster-zaehler.md","lastUpdated":null}'),d={name:"de/adapter/sourceanalytix/erste-schritte/erster-zaehler.md"};function s(h,e,l,u,o,c){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="mein-erster-zahler-in-10-minuten" tabindex="-1">Mein erster Zähler in 10 Minuten <a class="header-anchor" href="#mein-erster-zahler-in-10-minuten" aria-label="Permalink to &quot;Mein erster Zähler in 10 Minuten&quot;">​</a></h1><p><a id="start-values-unit"></a></p><h2 id="was-trage-ich-bei-den-startwerten-ein-und-in-welcher-einheit" tabindex="-1">Was trage ich bei den Startwerten ein (und in welcher Einheit)? <a class="header-anchor" href="#was-trage-ich-bei-den-startwerten-ein-und-in-welcher-einheit" aria-label="Permalink to &quot;Was trage ich bei den Startwerten ein (und in welcher Einheit)?&quot;">​</a></h2><p>Meist nichts. Lässt du die Felder leer, zählt jede Periode ab der Aktivierung, und SourceAnalytix setzt die Startwerte danach bei jedem Periodenwechsel selbst. Trägst du etwas ein, ist es ein Zählerstand, kein Verbrauch: der Stand zu Beginn der Periode, in der Einheit der Preisdefinition.</p><p>Der Verbrauch einer Periode ist der Gesamtstand minus ihr Startwert. Deshalb gehört in jedes Feld der Stand zu diesem Zeitpunkt (Systemzeit des ioBroker-Rechners):</p><table tabindex="0"><thead><tr><th>Feld</th><th>Stand am</th></tr></thead><tbody><tr><td>„Tag“</td><td>heute, 0:00 Uhr</td></tr><tr><td>„Woche“</td><td>Montag dieser Woche, 0:00 Uhr</td></tr><tr><td>„Monat“</td><td>1. dieses Monats, 0:00 Uhr</td></tr><tr><td>„Quartal“</td><td>1. Januar, April, Juli oder Oktober, 0:00 Uhr</td></tr><tr><td>„Jahr“</td><td>1. Januar, 0:00 Uhr</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Die Einheit ist die der Preisdefinition, nicht die des Datenpunkts. Liefert dein Zähler 12.345.678 Wh und der Preis rechnet in kWh, gehört in „Tag“ zum Beispiel <code>12340</code>, nicht <code>12340000</code>. Assistent und Detailansicht zeigen die Einheit hinter jedem Feld.</p></div><h3 id="wann-du-selbst-etwas-eintragst" tabindex="-1">Wann du selbst etwas einträgst <a class="header-anchor" href="#wann-du-selbst-etwas-eintragst" aria-label="Permalink to &quot;Wann du selbst etwas einträgst&quot;">​</a></h3><p>Nur wenn der Verbrauch vor der Aktivierung mitzählen soll, zum Beispiel der ganze Monat, obwohl du erst am 15. einrichtest. Dafür brauchst du die echten Stände von damals, etwa von einem Foto des Zählers.</p><ol><li>Wähle im Assistenten im Schritt „Startwerte“ die Karte „Verbrauch seit Periodenbeginn mitzählen“.</li><li>Trage die Stände ein, ohne Tausenderpunkt (<code>12475,5</code>). Ein einzelnes Komma oder ein einzelner Punkt ist immer das Dezimalzeichen. Kennst du einen Stand nicht, lass das Feld leer.</li><li>Unter jedem Feld steht „Verbrauch seit Beginn: …“ oder ein Fehler. Solange ein Feld einen Fehler zeigt, bleibt „Weiter“ gesperrt.</li><li>Schließe mit „⚡ Aktivieren“ ab.</li></ol><p>Beispiel: Du aktivierst am Mittwoch, 15. März, der Gesamtstand ist 12.480 kWh.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Eintrag</th><th>Verbrauch</th></tr></thead><tbody><tr><td>„Tag“</td><td><code>12475</code></td><td>5 kWh</td></tr><tr><td>„Woche“</td><td><code>12440</code></td><td>40 kWh</td></tr><tr><td>„Monat“</td><td><code>12300</code></td><td>180 kWh</td></tr><tr><td>„Quartal“</td><td><code>11900</code></td><td>580 kWh</td></tr><tr><td>„Jahr“</td><td><code>11900</code></td><td>580 kWh</td></tr></tbody></table><p>Kein Startwert darf größer als der Gesamtstand sein. „Tag“ ist der größte, „Monat“ ist mindestens so groß wie „Quartal“ und „Quartal“ mindestens so groß wie „Jahr“. „Woche“ richtet sich nach ihrem Beginn. Passt ein Wert erst geteilt durch 1000, fragt die Seite zum Beispiel „Sieht nach Wh aus – gemeint 1,29 kWh?“.</p><p>Bei einer laufenden Quelle änderst du die Startwerte in ihrer Detailansicht unter „Startwerte“ und übernimmst sie mit „⚡ Übernehmen“. Ein geleertes Feld zählt ab diesem Moment. Startwerte wirken nur bis zum nächsten Periodenwechsel, frühere Perioden lassen sich so nicht nachtragen. Bei einer Leistungsquelle (W) lässt du die Felder leer.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/zaehlerstaende-korrigieren#values-negative-after-entering-start">Warum sind meine Werte nach der Eingabe von Startwerten negativ?</a> · <a href="./../hintergrund/perioden-und-zeit#sourceanalytix-calculate-retroactively-only-activation">Berechnet SourceAnalytix rückwirkend?</a></p><p><a id="datapoint-enable-meter-kwh-power"></a></p><h2 id="welchen-datenpunkt-aktiviere-ich-zahler-kwh-oder-leistung-w" tabindex="-1">Welchen Datenpunkt aktiviere ich: Zähler (kWh) oder Leistung (W)? <a class="header-anchor" href="#welchen-datenpunkt-aktiviere-ich-zahler-kwh-oder-leistung-w" aria-label="Permalink to &quot;Welchen Datenpunkt aktiviere ich: Zähler (kWh) oder Leistung (W)?&quot;">​</a></h2><p>Nimm den Gesamtzähler deines Geräts, also den Wert in kWh, Wh oder m³, der nur steigt, zum Beispiel <code>ENERGY_Total</code> bei Tasmota oder <code>GAS_ENERGY</code> statt <code>GAS_POWER</code>. Einen Leistungswert in W nimmst du nur, wenn es keinen Zählerstand gibt.</p><table tabindex="0"><thead><tr><th></th><th>Zählerstand (kWh, m³ …)</th><th>Leistung (W, kW …)</th></tr></thead><tbody><tr><td>Rechnung</td><td>Gesamtstand minus Startwert</td><td>Leistung mal Zeit bis zum nächsten Wert</td></tr><tr><td>Genauigkeit</td><td>so genau wie der Zähler</td><td>Schätzung, je besser, je öfter das Gerät sendet</td></tr><tr><td>SourceAnalytix war gestoppt</td><td>nichts fehlt</td><td>die Energie der Pause fehlt</td></tr><tr><td>Gerät startet bei 0</td><td>wird als Reset erkannt</td><td>spielt keine Rolle</td></tr></tbody></table><p>Tageswerte wie <code>ENERGY_Today</code> oder „Ertrag heute“ sind ungeeignet. Der Assistent markiert sie mit „Tageszähler“. Sie funktionieren zwar, aber was das Gerät um Mitternacht zählt, fehlt.</p><h3 id="wenn-du-nur-einen-leistungswert-hast" tabindex="-1">Wenn du nur einen Leistungswert hast <a class="header-anchor" href="#wenn-du-nur-einen-leistungswert-hast" aria-label="Permalink to &quot;Wenn du nur einen Leistungswert hast&quot;">​</a></h3><p>Wähle im Assistenten die Messart „Leistung“ und eine Preisdefinition mit Energie-Einheit, zum Beispiel kWh. Der erste Wert ist nur der Ausgangspunkt, Verbrauch entsteht ab dem zweiten. In der Detailansicht unter „Einstellungen“ gibt es dafür drei Optionen:</p><ul><li>„Mittelwert bei Leistung“: rechnet mit dem Mittel aus zwei Werten. Passt zu Sensoren, die regelmäßig senden.</li><li>„Negative Werte ignorieren“: für Wechselrichter, die im Standby negative Leistung melden.</li><li>„Maximale Lücke zwischen Leistungswerten (Minuten)“: kommt länger kein Wert, zählt die Lücke als 0. Lass das Feld bei Geräten leer, die nur bei Änderung senden.</li></ul><p><strong>Siehe auch:</strong> <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">Wie rechnet SourceAnalytix Watt in kWh um?</a> · <a href="./../hintergrund/zaehler-reset#counter-reset-0-daily-happens">Zähler, der täglich auf 0 zurückgesetzt wird</a></p><p><a id="configure-sourceanalytix-datapoint"></a></p><h2 id="wo-konfiguriere-ich-sourceanalytix-fur-einen-datenpunkt" tabindex="-1">Wo konfiguriere ich SourceAnalytix für einen Datenpunkt? <a class="header-anchor" href="#wo-konfiguriere-ich-sourceanalytix-fur-einen-datenpunkt" aria-label="Permalink to &quot;Wo konfiguriere ich SourceAnalytix für einen Datenpunkt?&quot;">​</a></h2><p>In den Instanz-Einstellungen von SourceAnalytix. Im Tab „Übersicht“ startet „Quelle hinzufügen“ einen Assistenten, der die Quelle sofort aktiviert, ohne Neustart. Vorher brauchst du eine laufende Instanz und mindestens eine Preisdefinition.</p><ol><li><strong>„Datenpunkt“:</strong> Suche den Zählerstand oder wähle ihn über „Objekt auswählen“.</li><li><strong>„Messart“:</strong> „Zählerstand“ oder „Leistung“. Bei einem Zählerstand fragt der Assistent, ob der Wert manchmal auf 0 springt. „Ja“ schaltet die Reset-Erkennung ein.</li><li><strong>„Einheit“:</strong> Prüfe die erkannte Einheit.</li><li><strong>„Preis“:</strong> Wähle die Preisdefinition. Unpassende Einheiten sind mit „andere Einheit“ markiert. Bei einem Impulszähler (Einheit Stück) trägst du hier die Impulse pro Einheit ein, zum Beispiel 1000 bei 1000 imp/kWh.</li><li><strong>„Berechnung“:</strong> „Verbrauch“, „Kosten“ und „Zählerstände speichern“ sind vorbelegt.</li><li><strong>„Startwerte“:</strong> Lass „Ab jetzt zählen“ gewählt.</li><li><strong>„Name“:</strong> Gib einen Namen ein und klicke auf „⚡ Aktivieren“.</li></ol><p><img src="'+a+'" alt="Assistent „Quelle hinzufügen“, Schritt „Datenpunkt“ mit passenden Datenpunkten"></p><p>Danach wartet der Assistent auf den ersten Wert. Dauert das, etwa bei PV in der Nacht, kannst du ihn schließen. Die Quelle läuft weiter. Ihre Werte liegen unter <code>sourceanalytix.0.&lt;Gerät&gt;</code>, wobei <code>&lt;Gerät&gt;</code> die „Technische ID“ aus dem Namen ist.</p><p>Alle weiteren Einstellungen änderst du später in der Detailansicht der Quelle unter „Einstellungen“ und übernimmst sie mit „⚡ Übernehmen“. Löscht eine Änderung Daten, etwa wenn du „Verbrauch“ oder „Kosten“ ausschaltest, fragt die Seite vorher nach.</p><h3 id="und-am-datenpunkt-im-reiter-„objekte" tabindex="-1">Und am Datenpunkt im Reiter „Objekte“? <a class="header-anchor" href="#und-am-datenpunkt-im-reiter-„objekte" aria-label="Permalink to &quot;Und am Datenpunkt im Reiter „Objekte“?&quot;">​</a></h3><p>Dort steht nur ein Schalter, damit du im Objektbaum siehst, welche Datenpunkte SourceAnalytix nutzt. Schaltest du ihn ein, fehlt noch die Preisdefinition; die Quelle erscheint dann im Tab „Probleme“. Schaltest du ihn aus, entfernt das die Einstellungen der Quelle samt Startwerten. Zum Pausieren nimm „Deaktivieren“ in den Instanz-Einstellungen.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#datapoint-settings-costs-consumption-meter">Was bewirken die Einstellungen am Datenpunkt?</a> · <a href="./../fehlerbehebung/log-meldungen#datapoint-enabled-but-no-folders">Datenpunkt aktiviert, aber es entstehen keine Ordner</a></p><p><a id="values-consumption-today-yesterday"></a></p><h2 id="wo-finde-ich-meine-werte-tagesverbrauch-heute-gestern" tabindex="-1">Wo finde ich meine Werte (Tagesverbrauch heute/gestern)? <a class="header-anchor" href="#wo-finde-ich-meine-werte-tagesverbrauch-heute-gestern" aria-label="Permalink to &quot;Wo finde ich meine Werte (Tagesverbrauch heute/gestern)?&quot;">​</a></h2><p>Im Tab „Übersicht“: Jede Karte zeigt „Heute“, „Monat“ und „Jahr“, die Detailansicht unter „Werte“ auch „Gestern“, „Vormonat“ und mehr. Als States liegen sie unter <code>sourceanalytix.0.&lt;Gerät&gt;.currentYear</code>.</p><table tabindex="0"><thead><tr><th>State unter <code>sourceanalytix.0.&lt;Gerät&gt;</code></th><th>Inhalt</th></tr></thead><tbody><tr><td><code>cumulativeReading</code></td><td>Gesamtstand</td></tr><tr><td><code>currentYear.consumed.01_currentDay</code> bis <code>05_currentYear</code></td><td>heute, diese Woche, Monat, Quartal, Jahr</td></tr><tr><td><code>currentYear.consumed.01_previousDay</code> bis <code>05_previousYear</code></td><td>gestern, letzte Woche, Vormonat, Vorquartal, Vorjahr</td></tr><tr><td><code>currentYear.costs.…</code></td><td>Kosten mit denselben Namen</td></tr></tbody></table><p>Bei einer Einspeisung heißen die Ordner <code>delivered</code> und <code>earnings</code>. Die laufenden Werte erscheinen mit dem ersten Wert der Quelle, „gestern“ und die anderen Vorperioden erst nach dem ersten Periodenwechsel. SourceAnalytix rechnet nur, wenn die Quelle einen neuen Wert sendet.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Wo finde ich gestern, letzte Woche, letzten Monat?</a> · <a href="./../hintergrund/perioden-und-zeit#values-updated-live-midnight">Werte live oder erst um Mitternacht?</a></p>',40)])])}const p=t(d,[["render",s]]);export{m as __pageData,p as default};
